 29→// GetRewindPoints returns available rewind points.
 30→// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
 31→func (s *ManualCommitStrategy) GetRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
 32→	repo, err := OpenRepository(ctx)
 33→	if err != nil {
 34→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 35→	}
 36→
 37→	// Get checkpoint store
 38→	store, err := s.getCheckpointStore()
 39→	if err != nil {
 40→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
 41→	}
 42→
 43→	// Get current HEAD to find matching shadow branch
 44→	head, err := repo.Head()
 45→	if err != nil {
 46→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
 47→	}
 48→
 49→	// Find sessions for current HEAD
 50→	sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
 51→	if err != nil {
 52→		// Log error but continue to check for logs-only points
 53→		sessions = nil
 54→	}
 55→
 56→	var allPoints []RewindPoint
 57→
 58→	// Collect checkpoint points from active sessions using checkpoint.GitStore
 59→	// Cache session prompts by session ID to avoid re-reading the same prompt file
 60→	sessionPrompts := make(map[string]string)
 61→
 62→	for _, state := range sessions {
 63→		checkpoints, err := store.ListTemporaryCheckpoints(ctx, state.BaseCommit, state.WorktreeID, state.SessionID, limit)
 64→		if err != nil {
 65→			continue // Error reading checkpoints, skip this session
 66→		}
 67→
 68→		for _, cp := range checkpoints {
 69→			// Get session prompt (cached by session ID)
 70→			sessionPrompt, ok := sessionPrompts[cp.SessionID]
 71→			if !ok {
 72→				sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
 73→				sessionPrompts[cp.SessionID] = sessionPrompt
 74→			}
 75→
 76→			allPoints = append(allPoints, RewindPoint{
 77→				ID:               cp.CommitHash.String(),
 78→				Message:          cp.Message,
 79→				MetadataDir:      cp.MetadataDir,
 80→				Date:             cp.Timestamp,
 81→				IsTaskCheckpoint: cp.IsTaskCheckpoint,
 82→				ToolUseID:        cp.ToolUseID,
 83→				SessionID:        cp.SessionID,
 84→				SessionPrompt:    sessionPrompt,
 85→				Agent:            state.AgentType,
 86→			})
 87→		}
 88→	}
 89→
 90→	// Sort by date, most recent first
 91→	sort.Slice(allPoints, func(i, j int) bool {
 92→		return allPoints[i].Date.After(allPoints[j].Date)
 93→	})
 94→
 95→	if len(allPoints) > limit {
 96→		allPoints = allPoints[:limit]
 97→	}
 98→
 99→	// Also include logs-only points from commit history
100→	logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(ctx, limit)
101→	if err == nil && len(logsOnlyPoints) > 0 {
102→		// Build set of existing point IDs for deduplication
103→		existingIDs := make(map[string]bool)
104→		for _, p := range allPoints {
105→			existingIDs[p.ID] = true
106→		}
107→
108→		// Add logs-only points that aren't already in the list
109→		for _, p := range logsOnlyPoints {
110→			if !existingIDs[p.ID] {
111→				allPoints = append(allPoints, p)
112→			}
113→		}
114→
115→		// Re-sort by date
116→		sort.Slice(allPoints, func(i, j int) bool {
117→			return allPoints[i].Date.After(allPoints[j].Date)
118→		})
119→
120→		// Re-trim to limit
121→		if len(allPoints) > limit {
122→			allPoints = allPoints[:limit]
123→		}
124→	}
125→
126→	return allPoints, nil
127→}
