257→// ResolveLatestCheckpointFromMap picks the checkpoint with the latest CreatedAt
258→// from a list of checkpoint IDs. Filters to IDs present in infoMap, then picks
259→// the one with the most recent CreatedAt.
260→func ResolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo) (CheckpointInfo, bool) {
261→	var found bool
262→	var latest CheckpointInfo
263→	for _, cpID := range cpIDs {
264→		info, ok := infoMap[cpID]
265→		if !ok {
266→			continue
267→		}
268→		if !found || info.CreatedAt.After(latest.CreatedAt) {
269→			latest = info
270→			found = true
271→		}
272→	}
273→	return latest, found
274→}
