276→// Rewind restores the working directory to a checkpoint.
277→//
278→
279→func (s *ManualCommitStrategy) Rewind(ctx context.Context, w, errW io.Writer, point RewindPoint) error {
280→	repo, err := OpenRepository(ctx)
281→	if err != nil {
282→		return fmt.Errorf("failed to open git repository: %w", err)
283→	}
284→
285→	// Get the checkpoint commit
286→	commitHash := plumbing.NewHash(point.ID)
287→	commit, err := repo.CommitObject(commitHash)
288→	if err != nil {
289→		return fmt.Errorf("failed to get commit: %w", err)
290→	}
291→
292→	tree, err := commit.Tree()
293→	if err != nil {
294→		return fmt.Errorf("failed to get tree: %w", err)
295→	}
296→
297→	// Reset the shadow branch to the rewound checkpoint
298→	// This ensures the next checkpoint will only include prompts from this point forward
299→	if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
300→		// Log warning but don't fail - file restoration is the primary operation
301→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
302→	}
303→
304→	// Load session state to get untracked files that existed at session start
305→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
306→	var preservedUntrackedFiles map[string]bool
307→	if hasSessionTrailer {
308→		state, stateErr := s.loadSessionState(ctx, sessionID)
309→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
310→			preservedUntrackedFiles = make(map[string]bool)
311→			for _, f := range state.UntrackedFilesAtStart {
312→				preservedUntrackedFiles[f] = true
313→			}
314→		}
315→	}
316→
317→	// Build set of files in the checkpoint tree (excluding metadata)
318→	checkpointFiles := make(map[string]bool)
319→	err = tree.Files().ForEach(func(f *object.File) error {
320→		if err := ctx.Err(); err != nil {
321→			return err //nolint:wrapcheck // Propagating context cancellation
322→		}
323→		if !strings.HasPrefix(f.Name, entireDir) {
324→			checkpointFiles[f.Name] = true
325→		}
326→		return nil
327→	})
328→	if err != nil {
329→		return fmt.Errorf("failed to list checkpoint files: %w", err)
330→	}
331→
332→	// Get HEAD tree to identify tracked files
333→	head, err := repo.Head()
334→	if err != nil {
335→		return fmt.Errorf("failed to get HEAD: %w", err)
336→	}
337→	headCommit, err := repo.CommitObject(head.Hash())
338→	if err != nil {
339→		return fmt.Errorf("failed to get HEAD commit: %w", err)
340→	}
341→	headTree, err := headCommit.Tree()
342→	if err != nil {
343→		return fmt.Errorf("failed to get HEAD tree: %w", err)
344→	}
345→
346→	// Build set of files tracked in HEAD
347→	trackedFiles := make(map[string]bool)
348→	//nolint:errcheck // Error is not critical for rewind
349→	_ = headTree.Files().ForEach(func(f *object.File) error {
350→		if err := ctx.Err(); err != nil {
351→			return err //nolint:wrapcheck // Propagating context cancellation
352→		}
353→		trackedFiles[f.Name] = true
354→		return nil
355→	})
356→
357→	// Get repository root to walk from there
358→	repoRoot, err := paths.WorktreeRoot(ctx)
359→	if err != nil {
360→		repoRoot = "." // Fallback to current directory
361→	}
362→
363→	// Open os.Root at repo root for traversal-resistant file operations.
364→	// Defense-in-depth: paths come from git tree objects (trusted) but we
365→	// still scope operations to prevent any escape from the repo root.
366→	repoRootHandle, err := os.OpenRoot(repoRoot)
367→	if err != nil {
368→		return fmt.Errorf("failed to open repo root: %w", err)
369→	}
370→	defer repoRootHandle.Close()
371→
372→	// Find and delete untracked files that aren't in the checkpoint.
373→	// Uses git ls-files to only consider non-ignored files, avoiding walks through
374→	// large ignored directories like node_modules/.
375→	untrackedNow, err := collectUntrackedFiles(ctx)
376→	if err != nil {
377→		// Non-fatal - continue with restoration
378→		fmt.Fprintf(errW, "Warning: error listing untracked files: %v\n", err)
379→	}
380→	for _, relPath := range untrackedNow {
381→		// If file is in checkpoint, it will be restored
382→		if checkpointFiles[relPath] {
383→			continue
384→		}
385→
386→		// If file is tracked in HEAD, don't delete (user's committed work)
387→		if trackedFiles[relPath] {
388→			continue
389→		}
390→
391→		// If file existed at session start, preserve it (untracked user files)
392→		if preservedUntrackedFiles[relPath] {
393→			continue
394→		}
395→
396→		// File is untracked and not in checkpoint - delete it via os.Root
397→		if removeErr := osroot.Remove(repoRootHandle, relPath); removeErr == nil {
398→			fmt.Fprintf(w, "  Deleted: %s\n", relPath)
399→		}
400→	}
401→
402→	// Restore files from checkpoint
403→	err = tree.Files().ForEach(func(f *object.File) error {
404→		if err := ctx.Err(); err != nil {
405→			return err //nolint:wrapcheck // Propagating context cancellation
406→		}
407→		// Skip metadata directories - these are for checkpoint storage, not working dir
408→		if strings.HasPrefix(f.Name, entireDir) {
409→			return nil
410→		}
411→
412→		contents, err := f.Contents()
413→		if err != nil {
414→			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
415→		}
416→
417→		// Ensure directory exists (MkdirAll not available on os.Root)
418→		absPath := filepath.Join(repoRoot, f.Name)
419→		dir := filepath.Dir(absPath)
420→		if dir != "." {
421→			//nolint:gosec // G301: Need 0o755 for user directories during rewind
422→			if err := os.MkdirAll(dir, 0o755); err != nil {
423→				return fmt.Errorf("failed to create directory %s: %w", dir, err)
424→			}
425→		}
426→
427→		// Write file with appropriate permissions via os.Root
428→		var perm os.FileMode = 0o644
429→		if f.Mode == filemode.Executable {
430→			perm = 0o755
431→		}
432→		if err := osroot.WriteFile(repoRootHandle, f.Name, []byte(contents), perm); err != nil {
433→			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
434→		}
435→
436→		fmt.Fprintf(w, "  Restored: %s\n", f.Name)
437→		return nil
438→	})
439→	if err != nil {
440→		return fmt.Errorf("failed to iterate tree files: %w", err)
441→	}
442→
443→	fmt.Fprintln(w)
444→	if len(point.ID) >= 7 {
445→		fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID[:7])
446→	} else {
447→		fmt.Fprintf(w, "Restored files from shadow commit %s\n", point.ID)
448→	}
449→	fmt.Fprintln(w)
450→
451→	return nil
452→}
