495→// PreviewRewind returns what will happen if rewinding to the given point.
496→// This allows showing warnings about untracked files that will be deleted.
497→func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
498→	// Logs-only points don't modify the working directory
499→	if point.IsLogsOnly {
500→		return &RewindPreview{}, nil
501→	}
502→
503→	repo, err := OpenRepository(ctx)
504→	if err != nil {
505→		return nil, fmt.Errorf("failed to open git repository: %w", err)
506→	}
507→
508→	// Get the checkpoint commit
509→	commitHash := plumbing.NewHash(point.ID)
510→	commit, err := repo.CommitObject(commitHash)
511→	if err != nil {
512→		return nil, fmt.Errorf("failed to get commit: %w", err)
513→	}
514→
515→	tree, err := commit.Tree()
516→	if err != nil {
517→		return nil, fmt.Errorf("failed to get tree: %w", err)
518→	}
519→
520→	// Load session state to get untracked files that existed at session start
521→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
522→	var preservedUntrackedFiles map[string]bool
523→	if hasSessionTrailer {
524→		state, stateErr := s.loadSessionState(ctx, sessionID)
525→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
526→			preservedUntrackedFiles = make(map[string]bool)
527→			for _, f := range state.UntrackedFilesAtStart {
528→				preservedUntrackedFiles[f] = true
529→			}
530→		}
531→	}
532→
533→	// Build set of files in the checkpoint tree (excluding metadata)
534→	checkpointFiles := make(map[string]bool)
535→	var filesToRestore []string
536→	err = tree.Files().ForEach(func(f *object.File) error {
537→		if err := ctx.Err(); err != nil {
538→			return err //nolint:wrapcheck // Propagating context cancellation
539→		}
540→		if !strings.HasPrefix(f.Name, entireDir) {
541→			checkpointFiles[f.Name] = true
542→			filesToRestore = append(filesToRestore, f.Name)
543→		}
544→		return nil
545→	})
546→	if err != nil {
547→		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
548→	}
549→
550→	// Get HEAD tree to identify tracked files
551→	head, err := repo.Head()
552→	if err != nil {
553→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
554→	}
555→	headCommit, err := repo.CommitObject(head.Hash())
556→	if err != nil {
557→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
558→	}
559→	headTree, err := headCommit.Tree()
560→	if err != nil {
561→		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
562→	}
563→
564→	// Build set of files tracked in HEAD
565→	trackedFiles := make(map[string]bool)
566→	//nolint:errcheck // Error is not critical for preview
567→	_ = headTree.Files().ForEach(func(f *object.File) error {
568→		if err := ctx.Err(); err != nil {
569→			return err //nolint:wrapcheck // Propagating context cancellation
570→		}
571→		trackedFiles[f.Name] = true
572→		return nil
573→	})
574→
575→	// Find untracked files that would be deleted.
576→	// Uses git ls-files to only consider non-ignored files.
577→	var filesToDelete []string
578→	untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
579→	if untrackedErr != nil {
580→		fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
581→		return &RewindPreview{
582→			FilesToRestore: filesToRestore,
583→			FilesToDelete:  filesToDelete,
584→		}, nil
585→	}
586→	for _, relPath := range untrackedNow {
587→		if checkpointFiles[relPath] {
588→			continue
589→		}
590→		if trackedFiles[relPath] {
591→			continue
592→		}
593→		if preservedUntrackedFiles[relPath] {
594→			continue
595→		}
596→		filesToDelete = append(filesToDelete, relPath)
597→	}
598→
599→	// Sort for consistent output
600→	sort.Strings(filesToRestore)
601→	sort.Strings(filesToDelete)
602→
603→	return &RewindPreview{
604→		FilesToRestore: filesToRestore,
605→		FilesToDelete:  filesToDelete,
606→	}, nil
607→}
