759→// ResolveAgentForRewind resolves the agent from checkpoint metadata.
760→func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
761→	ag, err := agent.GetByAgentType(agentType)
762→	if err != nil {
763→		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
764→	}
765→	return ag, nil
766→}
