768→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
769→// Returns an empty string if the prompt cannot be read.
770→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
771→	// Get the commit and its tree
772→	commit, err := repo.CommitObject(commitHash)
773→	if err != nil {
774→		return ""
775→	}
776→
777→	tree, err := commit.Tree()
778→	if err != nil {
779→		return ""
780→	}
781→
782→	// Look for prompt.txt in the metadata directory
783→	promptPath := metadataDir + "/" + paths.PromptFileName
784→	promptEntry, err := tree.File(promptPath)
785→	if err != nil {
786→		return ""
787→	}
788→
789→	content, err := promptEntry.Contents()
790→	if err != nil {
791→		return ""
792→	}
793→
794→	return ExtractFirstPrompt(content)
795→}
